import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../core/api_paths.dart';
import '../../core/providers.dart';
import '../../state/app_state.dart';
import '../../widgets/async_panel.dart';
import '../../widgets/branch_selector.dart';

class HomeScreen extends ConsumerWidget{
 const HomeScreen({super.key});
 @override Widget build(BuildContext context,WidgetRef ref){final app=ref.watch(appStateProvider);final api=ref.watch(apiClientProvider);final branch=app.currentBranchId;return RefreshIndicator(onRefresh:()=>ref.read(appStateProvider.notifier).refreshBootstrap(),child:ListView(padding:const EdgeInsets.all(16),children:[Text('Home',style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:4),Text('${app.me['employee'] is Map ? (app.me['employee'] as Map)['full_name']??'' : ''}'),const SizedBox(height:12),const BranchSelector(),const SizedBox(height:16),Wrap(spacing:12,runSpacing:12,children:[_InfoCard(icon:Icons.store_outlined,label:'Branch',value:_branchName(app)),_InfoCard(icon:Icons.badge_outlined,label:'Designation',value:'${(app.me['employee'] as Map?)?['designation_code']??'-'}'),_InfoCard(icon:Icons.security_outlined,label:'Authority',value:'${app.branches.length} branch${app.branches.length==1?'':'es'}')]),const SizedBox(height:20),Text('Today',style:Theme.of(context).textTheme.titleLarge),const SizedBox(height:8),AsyncPanel(future:api.get(ApiPaths.attendanceToday),emptyMessage:'Aaj attendance start nahi hui.',builder:(context,data){if(data==null)return const Card(child:ListTile(leading:Icon(Icons.schedule),title:Text('Attendance pending'),subtitle:Text('Check-In karke duty start karein.')));final r=Map<String,dynamic>.from(data as Map);return Card(child:ListTile(leading:const Icon(Icons.verified_user_outlined),title:Text('${r['status']??'present'}'),subtitle:Text('Check-In: ${r['check_in_at']??'-'}\nCheck-Out: ${r['check_out_at']??'-'}'),isThreeLine:true));}),const SizedBox(height:16),if(branch!=null)AsyncPanel(reloadToken:branch,future:api.get(ApiPaths.performanceSummary,query:{'branch_id':branch,'from':_monthStart(),'to':_today(),'employee_id':(app.me['employee'] as Map?)?['id']}),emptyMessage:'Is month performance posting nahi hai.',builder:(context,data){final rows=(data as List).map((e)=>Map<String,dynamic>.from(e as Map)).toList();if(rows.isEmpty)return const SizedBox.shrink();final r=rows.first;return Card(child:ListTile(leading:const Icon(Icons.insights_outlined),title:const Text('Monthly Performance'),subtitle:Text('Points: ${r['points']} · Salary Fund: ₹${r['salary_fund']}')));})]));}
 String _branchName(AppState app){for(final b in app.branches){if(int.tryParse('${b['id']}')==app.currentBranchId)return'${b['name']}';}return'-';}
 static String _today(){final d=DateTime.now();return'${d.year.toString().padLeft(4,'0')}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';}
 static String _monthStart(){final d=DateTime.now();return'${d.year.toString().padLeft(4,'0')}-${d.month.toString().padLeft(2,'0')}-01';}
}
class _InfoCard extends StatelessWidget{const _InfoCard({required this.icon,required this.label,required this.value});final IconData icon;final String label,value;@override Widget build(BuildContext context)=>SizedBox(width:165,child:Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(icon),const SizedBox(height:8),Text(label,style:Theme.of(context).textTheme.labelMedium),const SizedBox(height:2),Text(value,maxLines:2,overflow:TextOverflow.ellipsis,style:Theme.of(context).textTheme.titleMedium)]))));}
